:root {
  color-scheme: light dark;
  --bg: #f6f2e9;
  --panel: #fffdf6;
  --fg: #231d15;
  --muted: #6f6353;
  --line: #ddd2bf;
  --accent: #0e6f5c;
  --accent-soft: #d9efe8;
  --code-bg: #f1eadb;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Times New Roman", serif;
  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14110d;
    --panel: #1c1813;
    --fg: #ede5d8;
    --muted: #a89a86;
    --line: #3b3327;
    --accent: #69d2b8;
    --accent-soft: #173b33;
    --code-bg: #211c15;
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font: 1.06rem/1.75 var(--serif);
  background: #f6f2e9;
  background: var(--bg);
  color: #231d15;
  color: var(--fg);
}
body::before {
  content: "";
  display: block;
  height: 6px;
  background: linear-gradient(90deg, var(--accent), transparent 65%);
}
::selection { background: var(--accent-soft); color: var(--fg); }

a {
  color: inherit;
  text-decoration: underline;
  text-decoration-color: var(--accent);
  text-underline-offset: 0.18em;
}
a:hover { color: var(--accent); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.strip {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 0.35rem 1.2rem;
  padding: 0.65rem 1rem;
  font: 0.78rem/1.4 var(--mono);
  letter-spacing: 0.02em;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  color: var(--muted);
}
.strip a {
  color: var(--fg);
  text-decoration: none;
  border-bottom: 1px dotted var(--accent);
  padding-bottom: 1px;
}
.strip a:hover { color: var(--accent); border-bottom-style: solid; }

.masthead, main, .colophon {
  max-width: 44rem;
  margin: 0 auto;
  padding-left: 1.1rem;
  padding-right: 1.1rem;
}
.masthead {
  padding-top: 2.7rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--line);
}
.masthead::before {
  content: "";
  display: block;
  width: 2.75rem;
  height: 4px;
  margin-bottom: 1.1rem;
  background: var(--accent);
  border-radius: 999px;
}
.avatar {
  display: block;
  width: 4.75rem;
  height: 4.75rem;
  margin-bottom: 1rem;
  border-radius: 20px;
  border: 1px solid var(--line);
  background: var(--panel);
  padding: 0.2rem;
}
.blog-title {
  font-size: clamp(2rem, 6vw, 2.8rem);
  line-height: 1.12;
  margin: 0;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.blog-title a { color: inherit; text-decoration: none; }
.blog-title a:hover { color: var(--accent); }
.tagline {
  margin: 0.6rem 0 0;
  color: var(--muted);
  font-size: 1.03rem;
  max-width: 36rem;
}

main {
  padding-top: 1.8rem;
  padding-bottom: 3rem;
  overflow-wrap: anywhere;
}
body.post .masthead { padding-bottom: 1.15rem; }
body.post main { padding-top: 1.45rem; }

.about {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 1.05rem 1.2rem 1.15rem;
  margin-bottom: 2.3rem;
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.04);
}
.about h2:first-child,
.about h3:first-child {
  margin-top: 0;
  font-family: var(--mono);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--accent);
}
.about p { margin: 0.65rem 0; }
.about ul, .about ol { margin: 0.7rem 0; padding-left: 1.3rem; }
.about li { margin: 0.3rem 0; }

.posts h2 {
  margin: 0 0 0.75rem;
  font-family: var(--mono);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--muted);
}
.post-list { list-style: none; margin: 0; padding: 0; }
.post-list li {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.25rem 1rem;
  padding: 0.8rem 0;
  border-bottom: 1px solid var(--line);
}
.post-list li:first-child { border-top: 1px solid var(--line); }
.post-link {
  color: var(--fg);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  padding-bottom: 0.12rem;
  background-image: linear-gradient(var(--accent), var(--accent));
  background-repeat: no-repeat;
  background-position: 0 100%;
  background-size: 0% 2px;
  transition: background-size 0.18s ease, border-color 0.18s ease;
}
.post-link:hover {
  background-size: 100% 2px;
  border-bottom-color: var(--accent);
  color: var(--fg);
}
.post-list time,
.post-header time {
  font-family: var(--mono);
  font-size: 0.8rem;
  color: var(--muted);
  white-space: nowrap;
}
.empty { color: var(--muted); font-style: italic; }

.post-header {
  margin-bottom: 1.9rem;
  padding-bottom: 1.1rem;
  border-bottom: 3px double var(--line);
}
.post-header h1 {
  font-size: clamp(1.85rem, 5vw, 2.4rem);
  line-height: 1.2;
  margin: 0 0 0.45rem;
  letter-spacing: -0.015em;
}
.post-header time { display: inline-block; }

.post-body { font-size: 1.075rem; }
.post-body p { margin: 1rem 0; }
.post-body h2,
.post-body h3,
.post-body h4 { line-height: 1.3; margin: 2.1rem 0 0.65rem; }
.post-body h2 {
  font-size: 1.36rem;
  padding-left: 0.7rem;
  border-left: 0.28rem solid var(--accent);
}
.post-body h3 { font-size: 1.17rem; }
.post-body h4 {
  font-size: 1.02rem;
  font-family: var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}
.post-body ul, .post-body ol { margin: 1rem 0; padding-left: 1.4rem; }
.post-body li { margin: 0.35rem 0; }
.post-body blockquote {
  margin: 1.4rem 0;
  padding: 0.8rem 1rem;
  border-left: 4px solid var(--accent);
  background: var(--panel);
  border-radius: 0 12px 12px 0;
}
.post-body blockquote p { margin: 0.5rem 0; }
.post-body pre {
  overflow-x: auto;
  margin: 1.3rem 0;
  padding: 0.9rem 1rem;
  background: var(--code-bg);
  border: 1px solid var(--line);
  border-radius: 12px;
  font: 0.86rem/1.55 var(--mono);
}
.post-body code {
  font-family: var(--mono);
  font-size: 0.92em;
  background: var(--code-bg);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0.08rem 0.35rem;
}
.post-body pre code {
  background: transparent;
  border: 0;
  padding: 0;
  font-size: 1em;
}
.post-body hr {
  border: 0;
  height: 1px;
  background: var(--line);
  width: min(100%, 16rem);
  margin: 2.2rem auto;
}

.notice {
  margin-top: 1.8rem;
  padding: 0.85rem 1rem;
  color: var(--muted);
  background: var(--panel);
  border: 1px dashed var(--line);
  border-radius: 12px;
}
